import{_ as i,a0 as p,w as s,s as a,I as r,x as n,a1 as l,A as o,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"如何在 AWS EC2 的 Linux 服務器上開放一個端口 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 AWS EC2 的 Linux 服務器上開放一個端口 | LCTT (201704) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 AWS EC2 的 Linux 服務器上開放一個端口 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 AWS EC2 的 Linux 服務器上開放一個端口 | LCTT (201704) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201704/20170309 How to open port on AWS EC2 Linux server","title":"如何在 AWS EC2 的 Linux 服務器上開放一個端口","tag":"201704","desc":""},"relativePath":"201704/20170309 How to open port on AWS EC2 Linux server.md","filePath":"[post].md"}'),d={name:"201704/20170309 How to open port on AWS EC2 Linux server.md"};function m(C,t,S,x,A,f){const e=p("Link");return s(),a("div",null,[t[19]||(t[19]=r("h1",{id:"如何在-aws-ec2-的-linux-服務器上開放一個端口",tabindex:"-1"},[n("如何在 AWS EC2 的 Linux 服務器上開放一個端口 "),r("a",{class:"header-anchor",href:"#如何在-aws-ec2-的-linux-服務器上開放一個端口","aria-label":"Permalink to “如何在 AWS EC2 的 Linux 服務器上開放一個端口”"},"​")],-1)),t[20]||(t[20]=r("p",null,[r("em",null,"這是一篇用屏幕截圖解釋如何在 AWS EC2 Linux 服務器上打開端口的教程。它能幫助你管理 EC2 服務器上特定端口的服務。")],-1)),t[21]||(t[21]=r("hr",null,null,-1)),t[22]||(t[22]=r("p",null,"AWS（即 Amazon Web Services）不是 IT 世界中的新術語了。它是亞馬遜提供的雲服務平台。它的免費帳户能為你提供一年的有限免費服務。這是嘗試新技術而不用花費金錢的最好的方式之一。",-1)),r("p",null,[t[1]||(t[1]=n("AWS 提供服務器計算作為他們的服務之一，他們稱之為 EC（彈性計算）。使用它可以構建我們的 Linux 服務器。我們已經看到了",-1)),l(e,{href:"http://kerneltalks.com/howto/install-ec2-linux-server-aws-with-screenshots/"},{default:o(()=>[...t[0]||(t[0]=[n("如何在 AWS 上設置免費的 Linux 服務器",-1)])]),_:1}),t[2]||(t[2]=n("了。",-1))]),t[23]||(t[23]=u('<p>默認情況下，所有基於 EC2 的 Linux 服務器都只打開 22 端口，即 SSH 服務端口（允許所有 IP 的入站連接）。因此，如果你託管了任何特定端口的服務，則要為你的服務器在 AWS 防火牆上打開相應端口。</p><p>同樣它的 1 到 65535 的端口是打開的（對於所有出站流量）。如果你想改變這個，你可以使用下面的方法編輯出站規則。</p><p>在 AWS 上為你的服務器設置防火牆規則很容易。你能夠在幾秒鐘內為你的服務器打開端口。我將用截圖指導你如何打開 EC2 服務器的端口。</p><h3 id="步驟-1" tabindex="-1">步驟 1 ： <a class="header-anchor" href="#步驟-1" aria-label="Permalink to “步驟 1 ：”">​</a></h3><p>登錄 AWS 帳户並進入 <strong>EC2 管理控制台</strong>。進入<ruby>“網絡及安全”<rt>Network &amp; Security </rt></ruby>菜單下的<ruby><strong>安全組</strong><rt>Security Groups</rt></ruby>，如下高亮顯示：</p><p><img src="http://cdn2.kerneltalks.com/wp-content/uploads/2017/03/AWS-EC2-management-console.jpg" alt="AWS EC2 management console"></p><p><em>AWS EC2 管理控制台</em></p><h3 id="步驟-2" tabindex="-1">步驟 2 : <a class="header-anchor" href="#步驟-2" aria-label="Permalink to “步驟 2 :”">​</a></h3><p>在<ruby>安全組<rt>Security Groups</rt></ruby>中選擇你的 EC2 服務器，並在 <ruby><strong>行動</strong><rt>Actions</rt></ruby> 菜單下選擇 <ruby><strong>編輯入站規則</strong><rt>Edit inbound rules</rt></ruby>。</p><p><img src="http://cdn2.kerneltalks.com/wp-content/uploads/2017/03/AWS-inbound-rules.jpg" alt="AWS inbound rules"></p><p><em>AWS 入站規則菜單</em></p><h3 id="步驟-3" tabindex="-1">步驟 3: <a class="header-anchor" href="#步驟-3" aria-label="Permalink to “步驟 3:”">​</a></h3><p>現在你會看到入站規則窗口。你可以在此處添加/編輯/刪除入站規則。這有幾個如 http、nfs 等列在下拉菜單中，它們可以為你自動填充端口。如果你有自定義服務和端口，你也可以定義它。</p><p><img src="http://cdn2.kerneltalks.com/wp-content/uploads/2017/03/AWS-add-inbound-rule.jpg" alt="AWS add inbound rule"></p><p><em>AWS 添加入站規則</em></p><p>比如，如果你想要打開 80 端口，你需要選擇：</p><ul><li>類型：http</li><li>協議：TCP</li><li>端口範圍：80</li><li>源：任何來源：打開 80 端口接受來自“任何IP（0.0.0.0/0）”的請求；我的 IP：那麼它會自動填充你當前的公共互聯網 IP</li></ul><h3 id="步驟-4" tabindex="-1">步驟 4: <a class="header-anchor" href="#步驟-4" aria-label="Permalink to “步驟 4:”">​</a></h3><p>就是這樣了。保存完畢後，你的服務器入站 80 端口將會打開！你可以通過 telnet 到 EC2 服務器公共域名的 80 端口來檢驗（可以在 EC2 服務器詳細信息中找到）。</p>',19)),r("p",null,[t[4]||(t[4]=n("你也可以在 ",-1)),l(e,{href:"http://ping.eu/port-chk/"},{default:o(()=>[...t[3]||(t[3]=[n("ping.eu",-1)])]),_:1}),t[5]||(t[5]=n(" 等網站上檢驗。",-1))]),t[24]||(t[24]=r("hr",null,null,-1)),t[25]||(t[25]=r("p",null,"同樣的方式可以編輯出站規則，這些更改都是即時生效的。",-1)),t[26]||(t[26]=r("hr",null,null,-1)),r("p",null,[t[7]||(t[7]=n("via: ",-1)),l(e,{href:"http://kerneltalks.com/virtualization/how-to-open-port-on-aws-ec2-linux-server/"},{default:o(()=>[...t[6]||(t[6]=[n("http://kerneltalks.com/virtualization/how-to-open-port-on-aws-ec2-linux-server/",-1)])]),_:1})]),r("p",null,[t[11]||(t[11]=n("作者：",-1)),l(e,{href:"http://kerneltalks.com/virtualization/how-to-open-port-on-aws-ec2-linux-server/"},{default:o(()=>[...t[8]||(t[8]=[n("Shrikant Lavhate",-1)])]),_:1}),t[12]||(t[12]=n(" 譯者：",-1)),l(e,{href:"https://github.com/geekpi"},{default:o(()=>[...t[9]||(t[9]=[n("geekpi",-1)])]),_:1}),t[13]||(t[13]=n(" 校對：",-1)),l(e,{href:"https://github.com/jasminepeng"},{default:o(()=>[...t[10]||(t[10]=[n("jasminepeng",-1)])]),_:1})]),r("p",null,[t[16]||(t[16]=n("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[14]||(t[14]=[n("LCTT",-1)])]),_:1}),t[17]||(t[17]=n(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:o(()=>[...t[15]||(t[15]=[n("Linux中國",-1)])]),_:1}),t[18]||(t[18]=n(" 榮譽推出",-1))])])}const W=i(d,[["render",m]]);export{k as __pageData,W as default};
